@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#eff5f2;--muted:#83918f;--line:rgba(207,231,224,.13);--panel:rgba(15,23,24,.87);--acid:#c9f36b;--red:#ff646b;--cyan:#7ad9d0;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#111719;color:var(--ink);font-family:var(--sans)}button{font:inherit;color:inherit}#game{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#192225}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.grain{pointer-events:none;position:absolute;inset:0;opacity:.1;z-index:2;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.25'/%3E%3C/svg%3E")}.vignette{pointer-events:none;position:absolute;z-index:1;inset:0;background:radial-gradient(ellipse at center,transparent 46%,rgba(5,11,12,.54) 100%)}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:72px;padding:0 30px;display:flex;align-items:center;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(10,16,17,.83),rgba(10,16,17,.25))}.brand{display:flex;align-items:center;gap:12px}.brand-mark{color:var(--acid);font-size:27px}.brand b{font-size:12px;letter-spacing:1.55px;display:block}.brand small{font-family:var(--mono);font-size:8px;letter-spacing:1.4px;color:#85918d;display:block;margin-top:3px}.round-pill{position:absolute;left:50%;transform:translateX(-50%);border:1px solid var(--line);border-radius:3px;background:rgba(8,14,15,.58);padding:10px 16px;font:10px var(--mono);letter-spacing:1px;color:#b8c2bd}.round-pill i,.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#df554f;box-shadow:0 0 10px #df554f;margin-right:8px}.round-pill span{color:#57645f;margin:0 8px}.round-pill b{color:#fff}.icon-btn{margin-left:auto;background:rgba(20,30,30,.6);border:1px solid var(--line);height:34px;width:36px;border-radius:3px;color:#aab8b2;cursor:pointer}.left-rail{position:absolute;z-index:4;left:26px;top:94px;width:202px;background:var(--panel);border:1px solid var(--line);padding:15px 13px 10px;backdrop-filter:blur(10px)}.rail-title{font:9px var(--mono);letter-spacing:1.2px;color:#98a6a0;display:flex;justify-content:space-between;padding-bottom:11px;border-bottom:1px solid var(--line)}.rail-title span{color:var(--acid);font-size:8px}.roster{padding:7px 0 5px}.roster-item{height:39px;display:flex;align-items:center;gap:9px;border-bottom:1px solid rgba(255,255,255,.05);font-size:11px;color:#c5cfca}.roster-item:last-child{border:0}.roster-item.dead{opacity:.42;text-decoration:line-through}.avatar{height:24px;width:24px;border-radius:5px;display:grid;place-items:center;font-size:12px;font-weight:700;color:#101719;box-shadow:inset 0 -4px 0 rgba(0,0,0,.15)}.roster-name{flex:1}.status-dot{height:5px;width:5px;border-radius:50%;background:#7fca83}.status-dot.dead{background:#e55858}.feed-wrap{margin-top:12px}.feed{height:89px;overflow:hidden;padding-top:5px}.feed-line{font:9px/1.5 var(--mono);color:#82918b;margin:5px 0}.feed-line strong{color:#c8d2cd;font-weight:400}.mission-card,.intel-card,.map-card{position:absolute;z-index:4;background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(10px)}.mission-card{bottom:23px;left:26px;width:252px;padding:15px 16px}.eyebrow{font:9px var(--mono);letter-spacing:1.4px;color:#96a49e}.live-dot{width:5px;height:5px;background:var(--acid);box-shadow:0 0 8px var(--acid)}.mission-head{display:flex;justify-content:space-between;align-items:center;margin-top:11px}.mission-head h1{font-size:15px;letter-spacing:.8px;margin:0}.tag{border:1px solid rgba(201,243,107,.3);color:var(--acid);font:8px var(--mono);padding:4px 6px;letter-spacing:1px}.tag.impostor{color:var(--red);border-color:rgba(255,100,107,.35)}.mission-card p{color:#96a29d;font-size:10px;line-height:1.55;margin:9px 0 12px}.progress-line{height:3px;background:#34403d}.progress-line div{height:100%;width:0;background:var(--acid);transition:width .3s}.progress-meta{display:flex;justify-content:space-between;margin-top:8px;font:8px var(--mono);letter-spacing:.6px;color:#82908b}.progress-meta b{color:#dfe9e3;font-weight:400}.task-list{margin-top:10px}.task-row{font:9px var(--mono);color:#9ba9a2;padding:4px 0;display:flex;gap:8px}.task-row i{font-style:normal;color:#58665f}.task-row.done{color:#66776d;text-decoration:line-through}.task-row.done i{color:var(--acid)}.right-stack{position:absolute;z-index:4;right:26px;top:94px;width:190px}.map-card,.intel-card{position:relative;width:100%;padding:12px}.map-label{font:9px var(--mono);letter-spacing:1px;color:#b9c5bf;display:flex;justify-content:space-between}.map-label span{color:var(--acid);font-size:8px}#minimap{width:100%;height:auto;margin:8px 0 4px;display:block}.map-legend{display:flex;gap:10px;font:7px var(--mono);color:#89958f}.map-legend span{display:flex;align-items:center;gap:4px}.dot{display:inline-block;width:5px;height:5px;border-radius:50%}.dot.you{background:#e9f2d8}.dot.crew{background:#50c9bb}.dot.threat{background:#ff6268}.intel-card{margin-top:9px}.intel-card .eyebrow{margin-bottom:9px}.intel-row{padding:8px 0;border-top:1px solid rgba(255,255,255,.07);display:flex;justify-content:space-between;font:8px var(--mono);color:#82908b;letter-spacing:.5px}.intel-row b{font-weight:400;color:#dce7df}.intel-row .threat-text{color:#e4c96e}.center-notice{position:absolute;z-index:5;top:20%;left:50%;transform:translate(-50%,-10px);padding:10px 15px;border:1px solid rgba(201,243,107,.28);background:rgba(10,17,17,.88);color:var(--acid);font:10px var(--mono);letter-spacing:1px;opacity:0;transition:.25s;pointer-events:none}.center-notice.show{opacity:1;transform:translate(-50%,0)}.interaction{position:absolute;z-index:4;left:50%;top:58%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:8px;opacity:0;transition:.15s;font:9px var(--mono);letter-spacing:1px;color:#e3e9e3}.interaction.show{opacity:1}.keycap{background:var(--acid);color:#182019;padding:5px 8px;border-radius:2px;font-weight:500}.action-hud{position:absolute;z-index:4;bottom:32px;right:240px;display:flex;align-items:center;gap:15px}.cooldown{border:1px solid var(--line);width:46px;height:46px;border-radius:50%;display:grid;place-items:center;position:relative;font:7px var(--mono);color:var(--acid);background:rgba(11,16,17,.65)}.cooldown-ring{position:absolute;inset:-3px;border:2px solid var(--acid);border-radius:50%;clip-path:polygon(0 0,100% 0,100% 100%,0 100%)}.controls-hint{font:8px var(--mono);letter-spacing:.7px;color:#a6b0ab}.controls-hint i{font-style:normal;color:#596660;padding:0 5px}.bottom-left{position:absolute;z-index:4;right:27px;bottom:29px;font:8px var(--mono);letter-spacing:.7px;color:#82908b}.bottom-left b{color:var(--acid);font-weight:400;margin-left:6px}.signal-bars{color:var(--acid);letter-spacing:-2px;margin-right:7px}.overlay{position:absolute;z-index:10;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(8,13,14,.82);backdrop-filter:blur(8px)}.start-panel{width:min(440px,calc(100% - 38px));padding:32px 38px 28px;border:1px solid rgba(201,243,107,.24);background:linear-gradient(145deg,rgba(26,37,36,.98),rgba(13,20,21,.98));box-shadow:0 25px 100px #0009;position:relative}.start-panel:before{content:'';position:absolute;left:-1px;top:36px;width:3px;height:68px;background:var(--acid)}.overline{font:9px var(--mono);letter-spacing:1.4px;color:#9daaa4}.overline span{display:inline-block;width:6px;height:6px;background:var(--acid);margin-right:8px}.hero-title{font-size:55px;line-height:.92;letter-spacing:-3px;font-weight:700;margin:26px 0 12px}.hero-title em{font-style:normal;color:var(--acid)}.hero-copy{font-size:13px;line-height:1.65;color:#aab6b0;margin:0 0 22px}.mode-card{display:flex;align-items:center;gap:12px;padding:12px;background:rgba(255,255,255,.035);border:1px solid var(--line)}.mode-icon{width:31px;height:31px;display:grid;place-items:center;background:rgba(201,243,107,.1);color:var(--acid);font-size:19px}.mode-card b,.mode-card small{display:block}.mode-card b{font:10px var(--mono);letter-spacing:.8px}.mode-card small{font:8px var(--mono);color:#84918b;margin-top:5px}.mode-status{margin-left:auto;color:var(--acid);font:8px var(--mono);letter-spacing:1px}.briefing{margin:18px 0}.briefing>span{font:8px var(--mono);letter-spacing:1.4px;color:var(--acid)}.briefing p{color:#a6b2ac;font-size:11px;line-height:1.6;margin:6px 0 0}.deploy-btn{width:100%;border:0;background:var(--acid);color:#152018;padding:14px 16px;text-align:left;font:600 10px var(--mono);letter-spacing:1px;cursor:pointer;transition:.2s}.deploy-btn:hover{background:#dcff8b;transform:translateY(-1px)}.deploy-btn span{float:right;font-size:16px;line-height:10px}.start-controls{font:8px var(--mono);color:#87948e;text-align:center;margin-top:16px;letter-spacing:.6px}.start-controls span{color:#d4ded8}.hidden{display:none!important}.meeting{position:absolute;z-index:9;inset:0;background:rgba(9,14,15,.94);display:grid;place-items:center;backdrop-filter:blur(8px)}.meeting-inner{width:min(680px,calc(100% - 34px));text-align:center}.meeting-kicker{font:9px var(--mono);letter-spacing:1.5px;color:var(--acid)}.meeting-inner h2{font-size:34px;letter-spacing:-1px;margin:14px 0 7px}.meeting-inner h2 em{font-style:normal;color:var(--red)}.meeting-inner>p{color:#96a39d;font-size:12px;margin:0 0 25px}.candidates{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.candidate{cursor:pointer;background:rgba(255,255,255,.045);border:1px solid var(--line);padding:14px 10px;transition:.18s}.candidate:hover,.candidate.selected{border-color:var(--acid);background:rgba(201,243,107,.09)}.candidate .avatar{margin:0 auto 8px;width:34px;height:34px}.candidate b{display:block;font:10px var(--mono);letter-spacing:.8px}.candidate small{display:block;color:#83918a;font:8px var(--mono);margin-top:5px}.candidate.skip{display:grid;place-content:center;color:#a0aaa4;font:10px var(--mono);min-height:88px}.meeting-footer{border-top:1px solid var(--line);margin-top:20px;padding-top:13px;display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:1px;color:#84918b}.meeting-footer b{color:var(--acid);font-size:15px}.end-panel .hero-title{font-size:45px}.mobile-controls{display:none}
@media(max-width:850px){.topbar{height:58px;padding:0 15px}.brand b{font-size:10px}.brand small{font-size:7px}.round-pill{font-size:8px;padding:8px}.left-rail{top:72px;left:12px;width:164px;padding:11px 9px}.roster-item{height:33px;font-size:10px}.avatar{width:21px;height:21px}.feed-wrap{display:none}.right-stack{right:12px;top:72px;width:142px}.map-card,.intel-card{padding:9px}.map-legend{gap:6px;font-size:6px}.intel-row{font-size:7px;padding:6px 0}.mission-card{left:12px;bottom:12px;width:min(236px,62vw);padding:11px}.mission-card p{font-size:9px;margin:7px 0}.mission-head h1{font-size:12px}.task-list{margin-top:6px}.task-row{font-size:8px;padding:3px 0}.action-hud{right:12px;bottom:15px;gap:7px;flex-direction:column-reverse;align-items:flex-end}.cooldown{width:39px;height:39px}.controls-hint{font-size:7px;text-align:right}.bottom-left{display:none}.mobile-controls{position:absolute;z-index:5;inset:auto 0 0;display:flex;justify-content:space-between;align-items:flex-end;padding:0 12px 110px;pointer-events:none}.dpad,.mobile-actions{pointer-events:auto}.dpad button,.mobile-actions button{background:rgba(13,21,21,.72);border:1px solid rgba(220,240,230,.2);color:#e8f1e9;border-radius:4px;backdrop-filter:blur(4px);touch-action:none}.dpad button{width:38px;height:34px;margin:2px;font-size:12px}.dpad>button{margin-left:42px}.mobile-actions{display:flex;flex-direction:column;gap:7px}.mobile-actions button{padding:11px 14px;font:9px var(--mono);letter-spacing:.8px}.mobile-actions #touchAction{color:var(--red);border-color:rgba(255,100,107,.4)}.mission-card{bottom:12px}.overlay{padding:10px}.start-panel{padding:26px 27px 22px}.hero-title{font-size:47px}.meeting-inner h2{font-size:25px}.candidate{padding:11px 5px}}
@media(max-width:480px){.left-rail{width:139px}.right-stack{width:122px}.intel-card{display:none}.mission-card{width:calc(100vw - 24px);bottom:10px;padding:9px 11px}.mission-card p{max-width:250px}.task-list{display:flex;gap:9px;flex-wrap:wrap}.task-row{font-size:7px}.action-hud{bottom:80px}.controls-hint{max-width:140px;line-height:1.6}.mobile-controls{padding-bottom:99px}.round-pill{left:auto;right:61px;transform:none}.brand-mark{font-size:22px}.map-legend{justify-content:space-between}.map-card{padding:7px}.map-card canvas{margin:5px 0 1px}.mode-card small{font-size:7px}.start-controls{font-size:7px}}

import * as THREE from '../vendor/three.module.js';

const $=s=>document.querySelector(s), canvas=$('#scene');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#172124'); scene.fog=new THREE.Fog('#172124',30,62);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.22;
const camera=new THREE.OrthographicCamera(-16,16,10,-10,.1,100); camera.position.set(13,20,16); camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight(0xc3e6dc,0x263230,2.1)); const sun=new THREE.DirectionalLight(0xffdfb7,3); sun.position.set(-7,16,9); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-22; sun.shadow.camera.right=22; sun.shadow.camera.top=22; sun.shadow.camera.bottom=-22; scene.add(sun);
const mats={floor:new THREE.MeshStandardMaterial({color:0x303b3c,roughness:.88}),wall:new THREE.MeshStandardMaterial({color:0x41494a,roughness:.78}),dark:new THREE.MeshStandardMaterial({color:0x172123,roughness:.72}),edge:new THREE.MeshStandardMaterial({color:0x64716e,metalness:.45,roughness:.45}),yellow:new THREE.MeshStandardMaterial({color:0xd9bf64,emissive:0x584719,emissiveIntensity:.3}),cyan:new THREE.MeshStandardMaterial({color:0x55cabc,emissive:0x1d665e,emissiveIntensity:.65}),red:new THREE.MeshStandardMaterial({color:0xf15f63,emissive:0x702327,emissiveIntensity:.5})};
const box=(x,y,z,sx,sy,sz,mat,collide=false)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);if(collide)obstacles.push({x,z,hx:sx/2,hz:sz/2});return m};
const obstacles=[]; const floor=new THREE.Mesh(new THREE.PlaneGeometry(34,26),mats.floor);floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);
// Industrial tactical arena, hard-cover lanes and two marked sites.
box(0,-.12,-13,34,.5,1.1,mats.dark,true); box(0,-.12,13,34,.5,1.1,mats.dark,true);box(-17,-.12,0,1.1,.5,27,mats.dark,true);box(17,-.12,0,1.1,.5,27,mats.dark,true);
for(let x=-15;x<=15;x+=2){box(x,.145,-12.39,.045,.02,.08,mats.edge);box(x,.145,12.39,.045,.02,.08,mats.edge)}
// cover modules
const cover=[[-7,-5,2.5,1.1],[-1,-5,1.4,1.1],[6,-4,2.5,1.1],[9,0,1.5,2.5],[-8,2,2.5,1.2],[-2,4,2.1,1.2],[5,4,3.2,1.2],[1,-.8,1.2,2.4]];
for(const [x,z,w,d] of cover){box(x,.65,z,w,1.3,d,mats.wall,true);box(x,.12,z,w+.12,.18,d+.12,mats.edge);box(x,1.33,z,w-.25,.07,d-.22,mats.dark)}
// elevated technical walkway strips and markings
for(const z of [-8.7,8.7]){box(0,.01,z,28,.025,.055,mats.cyan);for(let x=-12;x<=12;x+=4)box(x,.02,z,1.05,.03,.13,mats.yellow)}
function site(x,z,name){const disc=new THREE.Mesh(new THREE.CylinderGeometry(2.15,2.15,.055,48),new THREE.MeshStandardMaterial({color:0x2d594f,transparent:true,opacity:.27,roughness:.7}));disc.position.set(x,.03,z);scene.add(disc);const ring=new THREE.Mesh(new THREE.TorusGeometry(2.1,.035,6,56),mats.cyan);ring.rotation.x=Math.PI/2;ring.position.set(x,.07,z);scene.add(ring);for(let a=0;a<4;a++){const ang=a*Math.PI/2;box(x+Math.cos(ang)*2.12,.08,z+Math.sin(ang)*2.12,.3,.04,.12,mats.yellow)}label(name,x,.28,z,0xc9f36b)}
function label(text,x,y,z,color=0xc9f36b){const c=document.createElement('canvas');c.width=256;c.height=64;const ctx=c.getContext('2d');ctx.fillStyle='rgba(10,18,18,.82)';ctx.fillRect(0,0,256,64);ctx.fillStyle='#'+color.toString(16).padStart(6,'0');ctx.font='bold 27px monospace';ctx.textAlign='center';ctx.fillText(text,128,42);const tex=new THREE.CanvasTexture(c);const spr=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthTest:false}));spr.position.set(x,y,z);spr.scale.set(2.1,.53,1);scene.add(spr);return spr}
site(-11,-8,'SITE A');site(11,8,'SITE B');
function consoleModel(x,z,name,id){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);let base=new THREE.Mesh(new THREE.CylinderGeometry(.42,.48,.16,8),mats.edge);base.position.y=.1;g.add(base);let stem=new THREE.Mesh(new THREE.CylinderGeometry(.12,.17,.48,8),mats.dark);stem.position.y=.4;g.add(stem);let panel=new THREE.Mesh(new THREE.BoxGeometry(.8,.52,.15),new THREE.MeshStandardMaterial({color:0x526862,emissive:0x16352e,emissiveIntensity:.65,metalness:.3}));panel.position.set(0,.77,0);panel.rotation.x=-.24;g.add(panel);let screen=new THREE.Mesh(new THREE.PlaneGeometry(.58,.31),new THREE.MeshBasicMaterial({color:0x9de987}));screen.position.set(0,.78,.083);screen.rotation.x=-.24;g.add(screen);g.userData={x,z,name,id};label(name,x,1.45,z,0x8fe6ca);return g}
const taskDefs=[['POWER RELAY',-12,0],['DATA CORE',6,-8],['COMMS ARRAY',12,-2],['SECURITY FEED',-5,8],['VENTILATION',7,8],['BOMB SITE A',-11,-8],['BOMB SITE B',11,8]];
const consoles=taskDefs.map(([n,x,z],i)=>consoleModel(x,z,n,i));
// Central emergency beacon
const emergency=consoleModel(0,0,'EMERGENCY',99); emergency.scale.setScalar(1.13);
const colors=[0xf05c61,0x4ca9ee,0xf2bc4c,0x9d79e8,0x55c9a2,0xf18a46];
const names=['REDLINE','BLUEJAY','GOLDEN','VIOLET','PATCH','EMBER'];
function makeAgent(name,color,x,z,isPlayer=false){const root=new THREE.Group();root.position.set(x,0,z);scene.add(root);const c=new THREE.Color(color);const suit=new THREE.MeshStandardMaterial({color:c,roughness:.35,metalness:.12});const dark=new THREE.MeshStandardMaterial({color:0x172123,roughness:.6});const body=new THREE.Mesh(new THREE.CapsuleGeometry(.43,.62,5,10),suit);body.position.y=.7;body.castShadow=true;root.add(body);const visor=new THREE.Mesh(new THREE.BoxGeometry(.53,.31,.16),new THREE.MeshStandardMaterial({color:0x95dce1,metalness:.48,roughness:.18,emissive:0x28555a,emissiveIntensity:.3}));visor.position.set(0,1.02,.37);visor.castShadow=true;root.add(visor);const pack=new THREE.Mesh(new THREE.BoxGeometry(.3,.48,.28),dark);pack.position.set(0,.73,-.37);root.add(pack);const foot1=new THREE.Mesh(new THREE.BoxGeometry(.28,.18,.35),dark),foot2=foot1.clone();foot1.position.set(-.22,.13,.06);foot2.position.set(.22,.13,.06);root.add(foot1,foot2);const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x071010,transparent:true,opacity:.38}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.015;root.add(shadow);const halo=new THREE.Mesh(new THREE.TorusGeometry(.56,.035,6,32),new THREE.MeshBasicMaterial({color:isPlayer?0xc9f36b:color,transparent:true,opacity:.85}));halo.rotation.x=Math.PI/2;halo.position.y=.035;root.add(halo);const a={name,color,x,z,root,isPlayer,alive:true,isImpostor:false,heading:0,goal:null,taskDone:0,body:null,suspicion:0};root.rotation.y=Math.PI;return a}
const player=makeAgent('YOU',0xe8f1d8,0,-10,true);const bots=names.map((n,i)=>makeAgent(n,colors[i],[-13,-9,-4,4,9,13][i],[-3,3,7,-6,2,-1][i]));const agents=[player,...bots];
// a little scene dressing
for(const [x,z] of [[-15,-10],[15,-10],[-15,10],[15,10]]){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.06,.08,2.8,7),mats.edge);pole.position.set(x,1.4,z);scene.add(pole);const lamp=new THREE.PointLight(0x70e2cc,8,7,2);lamp.position.set(x,2.7,z);scene.add(lamp);const cap=new THREE.Mesh(new THREE.SphereGeometry(.15,10,8),mats.cyan);cap.position.copy(lamp.position);scene.add(cap)}
const state={running:false,ended:false,meeting:false,role:'crew',clock:120,killCooldown:0,killCount:0,reports:0,completed:0,totalTasks:12,meetingTimer:0,taskProgress:0,activeTask:null,meetingVotes:[],impostor:null,lastAction:0};
player.tasks=[0,1,2]; const key={};let moveTouch={x:0,z:0};
function setupRole(){const impIndex=Math.floor(Math.random()*agents.length);state.impostor=agents[impIndex];state.impostor.isImpostor=true;state.role=state.impostor===player?'impostor':'crew';$('#roleTag').textContent=state.role==='crew'?'CREW':'IMPOSTOR';$('#roleTag').className='tag '+(state.role==='impostor'?'impostor':'');$('#roleTitle').textContent=state.role==='crew'?'SECURE THE SITE':'ELIMINATE THE CREW';$('#missionCopy').textContent=state.role==='crew'?'Complete your assigned tasks. Keep your eyes open.':'Blend in. Take out the crew before they finish the job.';$('#briefingText').textContent=state.role==='crew'?'You are a CREWMATE. Complete your three assigned objectives, watch for suspicious movement, and report any bodies.':'You are the IMPOSTOR. Eliminate the crew, avoid being seen, and sabotage their operation.';$('#controlHint').innerHTML=state.role==='crew'?'WASD MOVE <i>·</i> E INTERACT <i>·</i> Q MEETING':'WASD MOVE <i>·</i> SPACE ELIMINATE <i>·</i> Q SABOTAGE';}
function startGame(){setupRole();state.running=true;$('#overlay').classList.add('hidden');document.activeElement?.blur();notice(state.role==='crew'?'OPERATION LIVE · COMPLETE YOUR OBJECTIVES':'YOU ARE THE IMPOSTOR · BLEND IN');updateUI();}
$('#startBtn').addEventListener('click',startGame);$('#againBtn').addEventListener('click',()=>location.reload());
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();key[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!state.running||state.ended)return;if(k==='e'||k===' ')interact();if(k==='q')callMeeting();if(k==='r')reportBody();if(k==='f'||k==='k')killAction()});window.addEventListener('keyup',e=>key[e.key.toLowerCase()]=false);
function buttonHold(btn,dir){const on=e=>{e.preventDefault();moveTouch=dir};const off=e=>{e.preventDefault();if(moveTouch===dir)moveTouch={x:0,z:0}};btn.addEventListener('pointerdown',on);['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,off))}
document.querySelectorAll('[data-dir]').forEach(b=>{const d=b.dataset.dir;buttonHold(b,{x:d==='left'?-1:d==='right'?1:0,z:d==='up'?-1:d==='down'?1:0})});$('#touchInteract').addEventListener('pointerdown',e=>{e.preventDefault();interact()});$('#touchAction').addEventListener('pointerdown',e=>{e.preventDefault();state.role==='impostor'?killAction():reportBody()});
$('#soundBtn').addEventListener('click',()=>{$('#soundBtn').textContent=$('#soundBtn').textContent==='♫'?'♪':'♫';notice('AUDIO '+($('#soundBtn').textContent==='♫'?'ON':'OFF'))});
function notice(text){const n=$('#notice');n.textContent=text;n.classList.add('show');clearTimeout(notice.t);notice.t=setTimeout(()=>n.classList.remove('show'),2100)}
function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
function nearestConsole(){let best=null,d=2.15;for(const c of consoles){const cd=Math.hypot(player.x-c.userData.x,player.z-c.userData.z);if(cd<d){best=c;d=cd}}return best}
function interact(){if(!state.running||state.meeting)return;const c=nearestConsole();if(state.role==='crew'&&c&&player.tasks.includes(c.userData.id)&&!c.userData.done){c.userData.done=true;player.taskDone++;state.completed++;$('#interactionText').textContent='';notice('OBJECTIVE COMPLETE · '+c.userData.name);updateUI();if(state.completed>=state.totalTasks)endGame(true,'All objectives secured. The facility is yours.');return}if(c?.userData.id===99){callMeeting();return}if(state.role==='impostor')killAction();else reportBody()}
function killAction(){if(!state.running||state.meeting||state.role!=='impostor'||state.killCooldown>0)return;let target=null,d=1.95;for(const a of bots){if(a.alive&&dist(player,a)<d){target=a;d=dist(player,a)}}if(!target){notice('NO TARGET IN RANGE');return}eliminate(target,true);state.killCooldown=14;$('#killCount').textContent=String(state.killCount).padStart(2,'0');}
function eliminate(a,playerKill=false){if(!a.alive)return;a.alive=false;a.root.visible=false;const bodyMesh=new THREE.Mesh(new THREE.CapsuleGeometry(.4,.55,4,8),new THREE.MeshStandardMaterial({color:a.color,roughness:.4}));bodyMesh.rotation.z=Math.PI/2;bodyMesh.position.set(a.x,.36,a.z);bodyMesh.castShadow=true;scene.add(bodyMesh);const visor=new THREE.Mesh(new THREE.BoxGeometry(.38,.23,.09),new THREE.MeshStandardMaterial({color:0x95dce1,metalness:.4}));visor.position.set(a.x,.62,a.z+.19);scene.add(visor);a.body={mesh:bodyMesh,x:a.x,z:a.z,reported:false};if(playerKill){state.killCount++;$('#killCount').textContent=String(state.killCount).padStart(2,'0');addFeed('YOU','target eliminated');notice('TARGET DOWN · '+a.name)}else{addFeed('COMMS','signal lost near '+(a.x<0?'WEST WING':'EAST WING'));notice('OPERATIVE DOWN · REPORT THE BODY');}refreshRoster()}
function reportBody(){if(!state.running||state.meeting)return;const body=agents.find(a=>a.body&&!a.body.reported&&dist(player,{x:a.body.x,z:a.body.z})<2.1);if(body){body.body.reported=true;state.reports++;$('#reportCount').textContent=String(state.reports).padStart(2,'0');callMeeting(body.name);return}notice('NO UNREPORTED BODY IN RANGE')}
function callMeeting(reason='EMERGENCY BEACON'){if(!state.running||state.meeting)return;if(reason==='EMERGENCY BEACON'&&dist(player,{x:0,z:0})>2.2){notice('GET TO THE EMERGENCY BEACON');return}state.meeting=true;state.meetingTimer=15;state.meetingVotes=[];$('#meetingReason').textContent=reason==='EMERGENCY BEACON'?'EMERGENCY BEACON':'BODY · '+reason;$('#meeting').classList.remove('hidden');buildCandidates();}
function buildCandidates(){const wrap=$('#candidates');wrap.innerHTML='';for(const a of agents){if(!a.alive)continue;const el=document.createElement('button');el.className='candidate';el.innerHTML=`<span class="avatar" style="background:#${a.color.toString(16).padStart(6,'0')}">${a.name==='YOU'?'◎':a.name[0]}</span><b>${a.name}</b><small>${a===player?'YOU':'OPERATIVE'}</small>`;el.onclick=()=>castVote(a);wrap.append(el)}const skip=document.createElement('button');skip.className='candidate skip';skip.innerHTML='<b>SKIP VOTE</b><small>NO EJECTION</small>';skip.onclick=()=>castVote(null);wrap.append(skip)}
function castVote(target){if(!state.meeting||state.playerVoted)return;state.playerVoted=true;state.meetingVotes.push({voter:player,target});$('#voteStatus').textContent='VOTE LOCKED · AWAITING SQUAD';document.querySelectorAll('.candidate').forEach(x=>x.disabled=true);notice(target?'VOTE CAST · '+target.name:'VOTE SKIPPED')}
function resolveMeeting(){state.meeting=false;state.playerVoted=false;$('#meeting').classList.add('hidden');const living=agents.filter(a=>a.alive);for(const bot of living.filter(a=>a!==player)){let pick=null;let likely=agents.find(a=>a.alive&&a!==bot&&a.body&&!a.body.reported);if(!likely&&Math.random()<.23)likely=player.alive?player:null;if(likely&&Math.random()<.43)pick=likely;state.meetingVotes.push({voter:bot,target:pick})}const tally=new Map();for(const v of state.meetingVotes)if(v.target)tally.set(v.target,(tally.get(v.target)||0)+1);let top=null,max=0,tie=false;for(const [a,n]of tally){if(n>max){top=a;max=n;tie=false}else if(n===max)tie=true}if(!top||tie||max<2){notice('VOTE TIED · NO EJECTION');addFeed('VOTE','no consensus — no ejection')}else{top.alive=false;top.root.visible=false;notice(top.isImpostor?'IMPOSTOR EJECTED':'INNOCENT EJECTED');addFeed('VOTE',top.name+' ejected · '+(top.isImpostor?'IMPOSTOR':'CREWMATE'));if(top.isImpostor){endGame(true,'The impostor was exposed. Vertigo is secure.');return}if(top===player){endGame(false,'You were ejected. The crew could not complete the mission.');return}}refreshRoster();checkWin()}
function sabotage(){if(state.role!=='impostor'||!state.running)return;const d=60;state.clock=Math.max(0,state.clock-d);for(const a of bots)if(a.alive)a.suspicion=Math.max(0,a.suspicion-1);notice('SABOTAGE · TIMER -60 SECONDS');addFeed('SYSTEM','round clock sabotaged')}
function addFeed(who,msg){const f=$('#feed'),row=document.createElement('div');row.className='feed-line';row.innerHTML='<strong>'+who+'</strong> · '+msg;f.prepend(row);while(f.children.length>4)f.lastChild.remove()}
function refreshRoster(){const r=$('#roster');r.innerHTML='';for(const a of agents){const el=document.createElement('div');el.className='roster-item'+(!a.alive?' dead':'');el.innerHTML=`<span class="avatar" style="background:#${a.color.toString(16).padStart(6,'0')}">${a.name==='YOU'?'◎':a.name[0]}</span><span class="roster-name">${a.name}${a===player?' <small>(YOU)</small>':''}</span><i class="status-dot ${a.alive?'':'dead'}"></i>`;r.append(el)}$('#aliveCount').textContent=agents.filter(a=>a.alive).length+' ALIVE'}
function updateUI(){refreshRoster();$('#taskCount').textContent=state.completed+' / '+state.totalTasks;$('#taskBar').style.width=(state.completed/state.totalTasks*100)+'%';const list=$('#taskList');list.innerHTML='';player.tasks.forEach(id=>{const d=taskDefs[id],done=consoles[id].userData.done;const row=document.createElement('div');row.className='task-row'+(done?' done':'');row.innerHTML='<i>'+(done?'✓':'○')+'</i>'+d[0];list.append(row)})}
function endGame(win,copy){if(state.ended)return;state.ended=true;state.running=false;$('#endTitle').innerHTML=win?'MISSION<br><em>COMPLETE.</em>':'MISSION<br><em>FAILED.</em>';$('#endCopy').textContent=copy;$('#endScreen').classList.remove('hidden')}
function checkWin(){const alive=agents.filter(a=>a.alive);if(!state.impostor.alive){endGame(true,'The impostor was exposed. Vertigo is secure.');return}if(state.impostor===player){if(alive.filter(a=>a!==player).length<=1)endGame(true,'You outnumbered the remaining crew. Clean work.')}else if(alive.filter(a=>a!==state.impostor).length<=1)endGame(false,'The impostor took control of the facility.')}

