const state={running:false,ended:false,meeting:false,role:'crew',clock:120,killCooldown:0,killCount:0,reports:0,completed:0,totalTasks:3,meetingTimer:0,playerVoted:false,meetingVotes:[],impostor:null};player.tasks=[0,1,2];const key={};let moveTouch={x:0,z:0};
