let noticeTimer=0,feedEntries=[];function announce(text,kind=''){const el=$('#notice');el.textContent=text;el.className='center-notice show '+kind;noticeTimer=2.5}
function feed(text){feedEntries.unshift(text);feedEntries=feedEntries.slice(0,4);const el=$('#feed');el.innerHTML=feedEntries.map((x,i)=>`<div class="feed-item" style="opacity:${1-i*.17}">${x}</div>`).join('')}
function refreshRoster(){const r=$('#roster');r.innerHTML='';for(const a of agents){const el=document.createElement('div');el.className='roster-item'+(!a.alive?' dead':'');el.innerHTML=`<span class="avatar" style="background:#${a.color.toString(16).padStart(6,'0')} color:#101719">${a===player?'◎':a.name[0]}</span><span class="roster-name">${a.name}${a===player?' <small>(YOU)</small>':''}</span><i class="status-dot ${a.alive?'':'dead'}"></i>`;r.append(el)}$('#aliveCount').textContent=agents.filter(a=>a.alive).length+' ALIVE'}
function updateUI(){refreshRoster();$('#taskCount').textContent=state.completed+' / '+state.totalTasks;$('#taskBar').style.width=(state.completed/state.totalTasks*100)+'%';const list=$('#taskList');list.innerHTML='';player.tasks.forEach(id=>{const d=taskDefs[id],done=consoles[id].userData.done,row=document.createElement('div');row.className='task-row'+(done?' done':'');row.innerHTML='<i>'+(done?'✓':'○')+'</i>'+d[0];list.append(row)});$('#killCount').textContent=String(state.killCount).padStart(2,'0');$('#reportCount').textContent=String(state.reports).padStart(2,'0');$('#roleTag').textContent=state.role==='impostor'?'IMPOSTOR':'CREW';$('#roleTag').classList.toggle('impostor',state.role==='impostor');$('#roleTitle').textContent=state.role==='impostor'?'ELIMINATE THE CREW':'SECURE THE SITE';$('#missionCopy').textContent=state.role==='impostor'?'Blend in. Eliminate the crew before they finish the objective.':'Complete your assigned tasks. Keep your eyes open.';$('#cooldown span').textContent=state.role==='impostor'?(state.killCooldown>0?Math.ceil(state.killCooldown)+'s':'READY'):'ACTION';$('#cooldown').classList.toggle('active',state.killCooldown<=0&&state.role==='impostor')}
function endGame(win,copy){if(state.ended)return;state.ended=true;state.running=false;$('#endTitle').innerHTML=win?'MISSION<br><em>COMPLETE.</em>':'MISSION<br><em>FAILED.</em>';$('#endCopy').textContent=copy;$('#endScreen').classList.remove('hidden')}
function beginMeeting(reason='EMERGENCY CALL'){if(!state.running||state.meeting)return;state.meeting=true;state.meetingTimer=15;state.playerVoted=false;state.meetingVotes=[];$('#meetingReason').textContent=reason;$('#meeting').classList.remove('hidden');$('#voteStatus').textContent='VOTE TO EJECT · SKIP IS ALLOWED';const c=$('#candidates');c.innerHTML='';agents.filter(a=>a.alive&&a!==player).forEach(a=>{const b=document.createElement('button');b.className='candidate';b.innerHTML=`<span class="avatar" style="background:#${a.color.toString(16).padStart(6,'0')}">${a.name[0]}</span><b>${a.name}</b>`;b.onclick=()=>castVote(a);c.append(b)});const skip=document.createElement('button');skip.className='candidate skip';skip.innerHTML='<b>SKIP VOTE</b>';skip.onclick=()=>castVote(null);c.append(skip);announce('MEETING CALLED','warning');feed('EMERGENCY COMMS OPEN')}
function castVote(target){if(!state.meeting||state.playerVoted)return;state.playerVoted=true;state.meetingVotes.push(target);$('#voteStatus').textContent='VOTE RECEIVED · AWAITING SQUAD';for(const a of agents){if(a.alive&&a!==player){let choice=Math.random()<.14?null:(Math.random()<.57?state.impostor:agents.filter(x=>x.alive&&x!==a&&x!==state.impostor)[Math.floor(Math.random()*Math.max(1,agents.filter(x=>x.alive&&x!==a&&x!==state.impostor).length))]);state.meetingVotes.push(choice)}}window.setTimeout(resolveMeeting,650)}
function resolveMeeting(){if(!state.meeting)return;const counts=new Map();state.meetingVotes.forEach(a=>{if(a)counts.set(a,(counts.get(a)||0)+1)});let ejected=null,max=0,tie=false;for(const[a,n]of counts){if(n>max){ejected=a;max=n;tie=false}else if(n===max)tie=true}if(tie)ejected=null;if(ejected){ejected.alive=false;ejected.root.visible=false;feed(ejected.name+' ejected · '+(ejected===state.impostor?'IMPOSTOR':'CREW'));announce(ejected.name+' EJECTED','warning')}else{feed('NO OPERATIVE EJECTED');announce('NO EJECTION','')}$('#meeting').classList.add('hidden');state.meeting=false;const aliveCrew=agents.filter(a=>a.alive&&a!==state.impostor).length,aliveImp=agents.filter(a=>a.alive&&a===state.impostor).length;if(!aliveImp)endGame(state.role==='crew','The impostor was ejected. Facility secured.');else if(aliveImp>=aliveCrew)endGame(state.role==='impostor','The impostor controls the facility. The crew has been eliminated.');else if(state.completed>=state.totalTasks)endGame(state.role==='crew','All field objectives are complete.')}
function eliminate(victim,killer){if(!victim.alive)return;victim.alive=false;victim.root.visible=false;victim.body={x:victim.root.position.x,z:victim.root.position.z,name:victim.name};if(killer===player){state.killCount++;updateUI();feed('TARGET NEUTRALIZED');announce('TARGET DOWN','warning')}else feed('OPERATIVE LOST · '+victim.name);const aliveCrew=agents.filter(a=>a.alive&&a!==state.impostor).length,aliveImp=agents.filter(a=>a.alive&&a===state.impostor).length;if(!aliveImp)endGame(state.role==='crew','The impostor is down. Facility secured.');else if(aliveImp>=aliveCrew)endGame(state.role==='impostor','The impostor controls the facility. The crew has been eliminated.')}
function startGame(){state.ended=false;state.running=true;state.clock=120;state.completed=0;state.killCount=0;state.reports=0;state.killCooldown=0;state.meeting=false;state.impostor=agents[Math.floor(Math.random()*agents.length)];state.role=state.impostor===player?'impostor':'crew';agents.forEach((a,i)=>{a.alive=true;a.root.visible=true;a.root.position.set(a.isPlayer?0:[-13,-9,-4,4,9][i-1],0,a.isPlayer?-10:[-3,3,7,-6,2][i-1]);a.goal=null;a.body=null;a.heading=0});taskDefs.forEach((_,i)=>{if(consoles[i])consoles[i].userData.done=false});player.tasks=state.role==='crew'?[0,1,2]:[];$('#overlay').classList.add('hidden');$('#endScreen').classList.add('hidden');$('#meeting').classList.add('hidden');$('#briefingText').textContent=state.role==='impostor'?'You are the impostor. Eliminate the crew and avoid suspicion.':'You are crew. Complete the marked field objectives and identify the impostor.';feedEntries=[];feed(state.role==='impostor'?'CLASSIFIED ROLE ASSIGNED':'SQUAD DEPLOYED');announce(state.role==='impostor'?'YOU ARE THE IMPOSTOR':'YOU ARE CREW',state.role==='impostor'?'warning':'');updateUI()}
$('#startBtn').addEventListener('click',startGame);$('#againBtn').addEventListener('click',startGame);$('#soundBtn').addEventListener('click',()=>{$('#soundBtn').classList.toggle('muted');announce('AUDIO '+($('#soundBtn').classList.contains('muted')?'MUTED':'ENABLED'))});
function interact(){if(!state.running||state.meeting)return;let nearest=null,nd=2.5;for(const c of consoles){const d=Math.hypot(player.root.position.x-c.userData.x,player.root.position.z-c.userData.z);if(d<nd){nearest=c;nd=d}}let body=null,bd=1.6;for(const a of agents){if(a.body){const d=Math.hypot(player.root.position.x-a.body.x,player.root.position.z-a.body.z);if(d<bd){body=a;bd=d}}}if(body){state.reports++;updateUI();beginMeeting('BODY REPORTED · '+body.body.name);return}if(nearest&&nearest.userData.id===99){beginMeeting('EMERGENCY CALL');return}if(state.role==='impostor'){let target=null,dmin=1.85;for(const a of agents){if(a!==player&&a.alive&&a!==state.impostor){const d=dist(player,a);if(d<dmin){target=a;dmin=d}}}if(target&&state.killCooldown<=0){eliminate(target,player);state.killCooldown=18;return}}if(nearest&&player.tasks.includes(nearest.userData.id)&&!nearest.userData.done){nearest.userData.done=true;state.completed++;updateUI();announce('OBJECTIVE COMPLETE','');feed('FIELD OBJECTIVE COMPLETE');if(state.completed>=state.totalTasks)endGame(state.role==='crew','Your squad completed every objective.');return}announce('NO VALID ACTION IN RANGE')}
function action(){if(!state.running||state.meeting)return;if(state.role==='impostor')interact();else{const body=agents.find(a=>a.body&&Math.hypot(player.root.position.x-a.body.x,player.root.position.z-a.body.z)<2.2);if(body){state.reports++;updateUI();beginMeeting('BODY REPORTED · '+body.body.name)}else beginMeeting('EMERGENCY CALL')}}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();key[k]=true;if(k==='e')interact();if(k==='q')action()});window.addEventListener('keyup',e=>key[e.key.toLowerCase()]=false);$('#touchInteract').addEventListener('click',interact);$('#touchAction').addEventListener('click',action);document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir,on=e=>{e.preventDefault();moveTouch[dir]=on===true};b.addEventListener('pointerdown',e=>{b.setPointerCapture(e.pointerId);on(e,true)});for(const ev of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>on(e,false))});
function blocked(x,z){if(Math.abs(x)>15.8||Math.abs(z)>11.8)return true;return obstacles.some(o=>Math.abs(x-o.x)<o.hx+.42&&Math.abs(z-o.z)<o.hz+.42)}
function moveAgent(a,dx,dz,speed,dt){if(!a.alive)return;let nx=a.root.position.x+dx*speed*dt,nz=a.root.position.z+dz*speed*dt;if(!blocked(nx,a.root.position.z))a.root.position.x=nx;if(!blocked(a.root.position.x,nz))a.root.position.z=nz;if(Math.hypot(dx,dz)>.01)a.root.rotation.y=Math.atan2(dx,dz)}
function botUpdate(dt){for(const a of bots){if(!a.alive||state.meeting)continue;a.think=(a.think||0)-dt;if(!a.goal||a.think<=0){a.think=1.2+Math.random()*1.7;if(a===state.impostor){let targets=agents.filter(x=>x!==a&&x.alive);a.goal=targets.length?targets[Math.floor(Math.random()*targets.length)].root.position.clone():null}else{let unfinished=taskDefs.slice(0,5).map((_,i)=>i).filter(i=>!consoles[i].userData.done);let id=unfinished.length?unfinished[Math.floor(Math.random()*unfinished.length)]:Math.floor(Math.random()*taskDefs.length);a.goal=new THREE.Vector3(taskDefs[id][1]+(Math.random()-.5),0,taskDefs[id][2]+(Math.random()-.5))}}if(a.goal){const dx=a.goal.x-a.root.position.x,dz=a.goal.z-a.root.position.z,d=Math.hypot(dx,dz);if(d<.8){if(a===state.impostor){const victim=agents.find(x=>x!==a&&x.alive&&dist(a,x)<1.2);if(victim&&Math.random()<.06)eliminate(victim,a)}a.goal=null}else moveAgent(a,dx/d,dz/d,a===state.impostor?1.38:1.04,dt)}}}
